public static int findNthLeapYear(int Y, int N) {
    // Validate input parameters
    if (Y <= 0) {
        throw new IllegalArgumentException("Start year Y must be a positive integer");
    }
    if (N <= 0) {
        throw new IllegalArgumentException("Position N must be a positive integer");
    }

    int count = 0;
    long year = Y;

    while (true) {
        // Determine if current year is a leap year
        boolean isLeap = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);

        if (isLeap) {
            count++;
            if (count == N) {
                // Ensure the result fits into an int
                if (year > Integer.MAX_VALUE) {
                    throw new IllegalStateException("Nth leap year exceeds int range");
                }
                return (int) year;
            }
        }

        year++;
        if (year > Integer.MAX_VALUE) {
            throw new IllegalStateException("Exceeded int range while searching for the Nth leap year");
        }
    }
}

