public static int calculateTimeNeeded(int N) {
    if (N < 3) {
        // For 0, 1, or 2 people, no swapping is required.
        return 0;
    }
    try {
        return 2 * (N - 3);
    } catch (Exception e) {
        // In the unlikely event of an arithmetic overflow or another error,
        // return -1 to indicate failure.
        return -1;
    }
}

