public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Validate input strings
    for (String s : strings) {
        if (s == null) {
            throw new IllegalArgumentException("Input strings must not be null");
        }
    }

    // Find maximum string length to limit search
    int maxLen = 0;
    for (String s : strings) {
        maxLen = Math.max(maxLen, s.length());
    }

    // If the longest possible substring has length 0, return 0
    if (maxLen == 0) {
        return 0;
    }

    String first = strings.get(0); // use the first string to generate candidates

    for (int len = maxLen; len >= 1; len--) {
        Set<String> candidates = new HashSet<>();

        // Build candidate substrings from the first string (and their reverses)
        for (int i = 0; i <= first.length() - len; i++) {
            String sub = first.substring(i, i + len);
            candidates.add(sub);
            String rev = new StringBuilder(sub).reverse().toString();
            candidates.add(rev);
        }

        // Test each candidate against all strings
        for (String cand : candidates) {
            boolean ok = true;
            String candRev = new StringBuilder(cand).reverse().toString();
            for (String s : strings) {
                if (!(s.contains(cand) || s.contains(candRev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len; // found the largest possible length
            }
        }
    }

    // If no substring satisfies the condition, return 0
    return 0;
}

