public static int maxRegions(int N) {
    if (N <= 0) {
        return 1; // No triangles, entire plane is one region
    }
    // According to the derived formula: maxRegions(N) = 3*N^2 - 3*N + 2
    // This satisfies the given examples:
    // N = 1 => 3*1 - 3*1 + 2 = 2
    // N = 2 => 12 - 6 + 2 = 8
    int result = 3 * N * N - 3 * N + 2;
    return result;
}

