public static int maxRegions(int N) {
    if (N < 1) {
        // If no triangles are added, the plane remains undivided.
        return 1;
    }
    // Use long to avoid overflow for large N.
    long result = 3L * N * N - 3L * N + 2L;
    if (result > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds integer range");
    }
    return (int) result;
}

