        return "cannot be travelled";
    }
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    if (sx < 0 || sx >= n || sy < 0 || sy >= n || ex < 0 || ex >= n || ey < 0 || ey >= n) {
        return "cannot be travelled";
    }
    java.util.Map<String, java.util.Set<String>> adj = new java.util.HashMap<>();
    // Helper to add adjacency
    java.util.function.BiConsumer<String, String> addEdge = (a, b) -> {
        adj.computeIfAbsent(a, k -> new java.util.HashSet<>()).add(b);
        adj.computeIfAbsent(b, k -> new java.util.HashSet<>()).add(a);
    };
    for (int[] p : paths) {
