public static String appx(String word1, String word2) {
    int len1 = word1.length();
    int len2 = word2.length();
    boolean[] present1 = new boolean[256];
    boolean[] present2 = new boolean[256];

    for (int i = 0; i < len1; i++) {
        present1[word1.charAt(i)] = true;
    }
    for (int i = 0; i < len2; i++) {
        present2[word2.charAt(i)] = true;
    }

    int common = 0;
    for (int i = 0; i < 256; i++) {
        if (present1[i] && present2[i]) {
            common++;
        }
    }

    int numerator = 2 * common;
    int denominator = len1 + len2;

    if (numerator == 0 || denominator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int a = numerator;
    int b = denominator;
    while (b != 0) {
        int temp = a % b;
        a = b;
        b = temp;
    }
    int gcd = a;

    int reducedNum = numerator / gcd;
    int reducedDen = denominator / gcd;

    String result;
    if (reducedDen == 1) {
        result = String.valueOf(reducedNum);
    } else {
        result = reducedNum + "/" + reducedDen;
    }

    return "appx(" + word1 + ", " + word2 + ") = " + result;
}

