        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int a = numerator;
    int b = denominator;
    while (b != 0) {
        int temp = a % b;
        a = b;
        b = temp;
    }
    int gcd = a;

    int reducedNum = numerator / gcd;
    int reducedDen = denominator / gcd;

    String result;
    if (reducedDen == 1) {
        result = String.valueOf(reducedNum);
    } else {
        result = reducedNum + "/" + reducedDen;
    }

    return "appx(" + word1 + ", " + word2 + ") = " + result;
}

