public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    int[] time = new int[n];
    Stack<int[]> stack = new Stack<>();
    stack.push(new int[]{0, -1, 0}); // node, parent, state (0=pre, 1=post)
    while (!stack.isEmpty()) {
        int[] cur = stack.pop();
        int node = cur[0];
        int parent = cur[1];
        int state = cur[2];
        if (state == 0) {
            stack.push(new int[]{node, parent, 1});
            for (int child : graph[node]) {
                if (child == parent) continue;
                stack.push(new int[]{child, node, 0});
            }
        } else {
            int total = 0;
            for (int child : graph[node]) {
                if (child == parent) continue;
                if (time[child] > 0 || hasApple[child]) {
                    total += time[child] + 2;
                }
            }
            time[node] = total;
        }
    }
    return time[0];
}

