public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char ch : s.toCharArray()) {
        freq.put(ch, freq.getOrDefault(ch, 0) + 1);
    }
    java.lang.StringBuilder res = new java.lang.StringBuilder();
    while (!freq.isEmpty()) {
        java.util.Iterator<java.util.Map.Entry<Character, Integer>> asc = freq.entrySet().iterator();
        while (asc.hasNext()) {
            java.util.Map.Entry<Character, Integer> entry = asc.next();
            char ch = entry.getKey();
            int cnt = entry.getValue();
            res.append(ch);
            cnt--;
            if (cnt == 0) {
                asc.remove();
            } else {
                entry.setValue(cnt);
            }
        }
        java.util.Iterator<java.util.Map.Entry<Character, Integer>> desc = freq.descendingMap().entrySet().iterator();
        while (desc.hasNext()) {
            java.util.Map.Entry<Character, Integer> entry = desc.next();
            char ch = entry.getKey();
            int cnt = entry.getValue();
            res.append(ch);
            cnt--;
            if (cnt == 0) {
                desc.remove();
            } else {
                entry.setValue(cnt);
            }
        }
    }
    return res.toString();
}

