public int minCostClimbingStairs(int[] cost) {
    // Handle null or empty input gracefully.
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // If there's only one step, you can start from the top directly without paying any cost.
    if (n <= 1) {
        return 0;
    }
    // dp[i] is represented by the variables prev1 (dp[i-2]) and prev2 (dp[i-1])
    int prev1 = cost[0]; // dp[0]
    int prev2 = cost[1]; // dp[1]
    // Compute dp[2] to dp[n-1]
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev1, prev2);
        prev1 = prev2;
        prev2 = curr;
    }
    // Minimum cost to reach the top is the min of dp[n-1] and dp[n-2]
    return Math.min(prev1, prev2);
}

