        int curr = cost[i] + Math.min(prev1, prev2);
        prev1 = prev2;
        prev2 = curr;
    }
    // Minimum cost to reach the top is the min of dp[n-1] and dp[n-2]
    return Math.min(prev1, prev2);
}

