                unmatchedOpen--;
            } else {
                insertions++; // need an opening bracket before this closing
            }
        } else {
            // If the character is not '(' or ')', it is unexpected.
            // According to the problem, s should only contain '(' and ')'.
            // We ignore any other characters.
        }
    }
    return insertions + unmatchedOpen;
}

