public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer.");
    }
    // Generate Fibonacci numbers up to k
    int[] fibs = new int[50];
    fibs[0] = 1;
    fibs[1] = 1;
    int fibCount = 2;
    while (true) {
        long next = (long) fibs[fibCount - 1] + fibs[fibCount - 2];
        if (next > k || next > Integer.MAX_VALUE) {
            break;
        }
        fibs[fibCount] = (int) next;
        fibCount++;
    }
    int count = 0;
    int remaining = k;
    for (int i = fibCount - 1; i >= 0 && remaining > 0; i--) {
        while (remaining >= fibs[i]) {
            remaining -= fibs[i];
            count++;
        }
    }
    return count;
}

