public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();
    int limit = (int)Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small.add(i);
            int counterpart = n / i;
            if (counterpart != i) {
                large.add(counterpart);
            }
        }
    }
    int smallSize = small.size();
    int total = smallSize + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= smallSize) {
        return small.get(k - 1);
    } else {
        int indexInLarge = large.size() - (k - smallSize);
        return large.get(indexInLarge);
    }
}

