public int maxUniqueSplit(String s) {
    int n = s.length();
    int max = 1; // at least whole string as one substring
    int totalMasks = 1 << (n - 1);
    for (int mask = 0; mask < totalMasks; mask++) {
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        int start = 0;
        int count = 0;
        boolean valid = true;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) {
                String sub = s.substring(start, i + 1);
                if (!seen.add(sub)) {
                    valid = false;
                    break;
                }
                count++;
                start = i + 1;
            }
        }
        if (!valid) continue;
        String last = s.substring(start);
        if (!seen.add(last)) continue;
        count++;
        if (count > max) {
            max = count;
        }
    }
    return max;
}

