public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty.");
    }

    int result = 0;

    // Iterate over all 32 bit positions
    for (int bit = 0; bit < 32; bit++) {
        int count = 0;

        // Count how many times the current bit is set among the elements
        for (int num : nums) {
            if (((num >> bit) & 1) == 1) {
                count++;
            }
        }

        // If the bit count mod 3 is not zero, this bit belongs to the unique number
        if ((count % 3) != 0) {
            result |= (1 << bit);
        }
    }

    return result;
}

