public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    for (long factor = 1; n / factor != 0; factor *= 10) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
    }
    return (int) count;
}

