public static int longestLine(int[][] mat) {
    try {
        if (mat == null || mat.length == 0) {
            return 0;
        }
        int m = mat.length;
        int n = mat[0].length;
        if (n == 0) {
            return 0;
        }
        int[][] hor = new int[m][n];
        int[][] ver = new int[m][n];
        int[][] diag = new int[m][n];
        int[][] anti = new int[m][n];
        int max = 0;
        for (int i = 0; i < m; i++) {
            // In case of jagged arrays, ensure each row has the same length
            if (mat[i] == null || mat[i].length != n) {
                return 0;
            }
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    hor[i][j] = (j > 0 ? hor[i][j - 1] : 0) + 1;
                    ver[i][j] = (i > 0 ? ver[i - 1][j] : 0) + 1;
                    diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                    anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                    int localMax = Math.max(Math.max(hor[i][j], ver[i][j]),
                                            Math.max(diag[i][j], anti[i][j]));
                    if (localMax > max) {
                        max = localMax;
                    }
                } else {
                    hor[i][j] = 0;
                    ver[i][j] = 0;
                    diag[i][j] = 0;
                    anti[i][j] = 0;
                }
            }
        }
        return max;
    } catch (Exception e) {
        return 0;
    }
}

