public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) return 0;
    int n = A.length;
    int max = 0;
    for (int v : A) if (v > max) max = v;
    int maxSum = 2 * max;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    java.util.Arrays.sort(A);
    boolean[] visited = new boolean[n];
    class Solver {
        int solve(int lastVal) {
            boolean allVisited = true;
            for (boolean v : visited) {
                if (!v) { allVisited = false; break; }
            }
            if (allVisited) return 1;
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                if (visited[i]) continue;
                if (i > 0 && A[i] == A[i - 1] && !visited[i - 1]) continue;
                if (lastVal != -1) {
                    int sum = lastVal + A[i];
                    if (sum > maxSum || !isSquare[sum]) continue;
                }
                visited[i] = true;
                cnt += solve(A[i]);
                visited[i] = false;
            }
            return cnt;
        }
    }
    return new Solver().solve(-1);
}

