public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    if (n == 1) return 1;
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);
    int fullMask = (1 << n) - 1;
    int[][] memo = new int[1 << n][n];
    for (int i = 0; i < (1 << n); i++) {
        for (int j = 0; j < n; j++) memo[i][j] = -1;
    }

    java.util.function.IntBinaryOperator isPerfectSquare = sum -> {
        long s = sum;
        long r = (long) Math.sqrt(s);
        return (int) (r * r == s ? 1 : 0);
    };

    java.util.function.Function<Integer, Integer> dfs = new java.util.function.Function<Integer, Integer>() {
        @Override
        public Integer apply(Integer maskLast) {
            int mask = maskLast >> 4;
            int last = maskLast & 15; // store last index in lower bits
            if (mask == fullMask) return 1;
            int res = 0;
            for (int j = 0; j < n; j++) {
                if ((mask & (1 << j)) != 0) continue;
                if (last != -1) {
                    long sum = (long) arr[last] + (long) arr[j];
                    long r = (long) Math.sqrt(sum);
                    if (r * r != sum) continue;
                }
                if (j > 0 && arr[j] == arr[j - 1] && (mask & (1 << (j - 1))) == 0) continue;
                res += dfs.apply((mask | (1 << j)) << 4 | j);
            }
            return res;
        }
    };

    int total = 0;
    for (int j = 0; j < n; j++) {
        if (j > 0 && arr[j] == arr[j - 1]) continue; // skip duplicates for first position
        total += dfs.apply((1 << j) << 4 | j);
    }
    return total;
}

