public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1; // invalid input
    }
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;
    // Find the first index from the right where digits[i] < digits[i+1]
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // already the highest permutation
    }
    int j = digits.length - 1;
    // Find the first index from the right that is greater than digits[i]
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }
    // Swap
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Reverse the suffix starting at i+1
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    // Convert back to int
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        // Overflow case
        return -1;
    }
}

