public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(n);
    if (n <= 0) {
        return result;
    }
    long cur = 1;
    while (result.size() < n) {
        result.add((int) cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else {
            if (cur % 10 != 9 && cur + 1 <= n) {
                cur++;
            } else {
                while ((cur / 10) % 10 == 9) {
                    cur /= 10;
                }
                cur++;
            }
        }
    }
    return result;
}

